export const meta = {
  name: 'agent-plugins-integration-research',
  description: 'Widen research beyond TDAD/spec-driven-UI and synthesize concrete integration proposals for agent-plugins',
  phases: [
    { title: 'Research' },
    { title: 'Ideate' },
    { title: 'Critique' },
    { title: 'Synthesize' },
  ],
}

const RESEARCH_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['findings', 'reasoning'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['topic', 'finding', 'relevance'],
        properties: {
          topic: { type: 'string' },
          finding: { type: 'string' },
          source: { type: 'string' },
          relevance: { type: 'string', description: 'why this matters to agent-plugins' },
        },
      },
    },
    reasoning: { type: 'string' },
  },
}

const PROPOSAL_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['proposals'],
  properties: {
    proposals: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['title', 'description', 'target_files', 'effort', 'impact', 'rationale'],
        properties: {
          title: { type: 'string' },
          description: { type: 'string' },
          target_files: { type: 'array', items: { type: 'string' } },
          effort: { enum: ['low', 'medium', 'high'] },
          impact: { enum: ['low', 'medium', 'high'] },
          rationale: { type: 'string' },
        },
      },
    },
  },
}

const CRITIQUE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['title', 'verdict', 'reasoning'],
  properties: {
    title: { type: 'string' },
    verdict: { enum: ['keep', 'reject', 'modify'] },
    reasoning: { type: 'string' },
    modification: { type: 'string' },
  },
}

phase('Research')
log('Fanning out 5 research agents: 2 external web sweeps, 3 repo deep-reads')

const researchTasks = [
  () => agent(
    `Web-research regression-prevention and test-impact-analysis techniques for AI coding agents, beyond the "TDAD" paper (test-code dependency graphs, pre-change impact maps, P2P regression metrics). Look for: SWE-bench regression analysis follow-ups, regression test selection (RTS) literature applied to LLM agents, mutation-testing-guided agents, other 2025/2026 papers on agentic coding safety/regression. Search the web. Return findings with topic/finding/source/relevance.`,
    { label: 'web:regression-research', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Web-research spec-driven development, schema governance, and "generated over authored" tooling beyond Nathan Curtis's spec-driven-UI article. Look for: OpenAPI/protobuf breaking-change detection tools (e.g. buf breaking, oasdiff), JSON Schema versioning best practices, design-token pipelines (Style Dictionary, Tokens Studio), contract-testing approaches (Pact), and any 2025/2026 writing on treating specs as a build artifact rather than documentation. Search the web. Return findings with topic/finding/source/relevance.`,
    { label: 'web:spec-governance-research', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Read the agent-plugins repo at /Users/gabe/Projects/agent-plugins deeply, focused on the lambda plugin (plugins/lambda/agents/*.md, plugins/lambda/skills/) and the shared schemas it touches (shared/schemas/plan@1.json, shared/schemas/verdict@2.json, shared/schemas/mutation-report@1.json). Also read shared/constitution.md sections on Subsystem Compilation Batching and Epistemic Stopping. Identify precisely, with file:line pointers, where lambda currently has NO mechanism for pre-change blast-radius / test-impact analysis before implementer starts a task, and where reviewer's "sibling gaps" check relies on pattern-matching a hazards reference rather than a computed call graph. Return findings (topic/finding/relevance) citing exact file paths and line numbers as evidence.`,
    { label: 'repo:lambda-scan', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Read the agent-plugins repo at /Users/gabe/Projects/agent-plugins deeply, focused on the proof plugin (plugins/proof/agents/*.md) and shared/schemas/field-survival-map@1.json, shared/schemas/candidate@1.json, shared/schemas/finding-report@1.json, plus shared/references/rust-hazards-t7-t10.md and typescript-hazards-t7-t10.md. boundary-tracer already computes a field-survival dependency trace for T7/T10 hazards. Assess: could this tracing capability generalize into a shared "impact map" primitive reusable by both proof (field survival) and lambda (test impact), instead of two separate implementations? Return findings with file:line evidence for how boundary-tracer currently works and what would need to change to generalize it.`,
    { label: 'repo:proof-scan', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Read the agent-plugins repo at /Users/gabe/Projects/agent-plugins deeply, focused on: shared/constitution.md (all sections), scripts/check-versions.sh, scripts/check-skills-doc.sh, scripts/check-reference-size.sh, plugins/basis/agents/*.md (scaffolder and auditor), and every plugins/*/plugin.json's "skills" and "agents" fields versus the actual files on disk (use ls/find to check for drift). Determine: (1) is there any automated check that a shared/schemas/*.json breaking change was accompanied by a version bump per constitution rule about immutable schemas, (2) is plugin.json's skills/agents list ever auto-generated or only hand-authored, (3) does basis:auditor or scaffolder check either of these today. Return findings with file:line evidence.`,
    { label: 'repo:governance-scan', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
]

const researchResults = (await parallel(researchTasks)).filter(Boolean)
const allFindings = researchResults.flatMap(r => r.findings || [])
log(`Collected ${allFindings.length} findings across ${researchResults.length} research agents`)

phase('Ideate')
const findingsText = JSON.stringify(allFindings, null, 2)

const angles = [
  {
    key: 'regression-impact',
    prompt: `You are proposing concrete changes to the agent-plugins repo (/Users/gabe/Projects/agent-plugins) based on this research on regression-prevention and test-impact-analysis for coding agents:\n\n${findingsText}\n\nFocus your proposals on the lambda and proof plugins: how should pre-change impact analysis, blast-radius computation, or regression-vs-new-failure distinction be integrated? Read the actual files you'd need to change before proposing (use your file tools) so target_files and rationale are grounded in real current content, not assumption. Produce 2-4 concrete, scoped proposals.`,
  },
  {
    key: 'schema-governance',
    prompt: `You are proposing concrete changes to the agent-plugins repo (/Users/gabe/Projects/agent-plugins) based on this research on spec-driven development, schema governance, and generated-vs-authored tooling:\n\n${findingsText}\n\nFocus your proposals on shared/schemas/, shared/constitution.md's Schema-Driven Handoffs rules, plugin.json manifest accuracy, and the scripts/check-*.sh family. Read the actual files you'd need to change before proposing. Produce 2-4 concrete, scoped proposals.`,
  },
  {
    key: 'self-improvement',
    prompt: `You are proposing concrete changes to the agent-plugins repo (/Users/gabe/Projects/agent-plugins) based on this research:\n\n${findingsText}\n\nOne notable finding is that an iterative self-improvement loop that repeatedly simplifies an agent's own instructions (measuring the effect against a real outcome) massively outperformed a one-shot hand-authored skill. Focus your proposals on basis (plugins/basis/agents/*.md) and whether/how an iterative, outcome-measured prompt-simplification loop could be added there, distinct from its current conformance-auditing role. Read the actual files first. Produce 2-3 concrete, scoped proposals — be skeptical of scope creep and say so if the idea doesn't actually fit this repo's architecture.`,
  },
  {
    key: 'cross-cutting',
    prompt: `You are proposing concrete changes to the agent-plugins repo (/Users/gabe/Projects/agent-plugins) based on this research:\n\n${findingsText}\n\nFocus on anything NOT already covered by lambda/proof regression-impact work, schema governance, or basis self-improvement — e.g. canon, vector, delta, axiom, graph, trace plugins, or cross-plugin orchestration patterns. Read the actual files first. Produce 2-4 concrete, scoped proposals grounded in real file content.`,
  },
]

const ideationResults = (await parallel(angles.map(a => () =>
  agent(a.prompt, { label: `ideate:${a.key}`, phase: 'Ideate', schema: PROPOSAL_SCHEMA })
))).filter(Boolean)

const allProposals = ideationResults.flatMap(r => r.proposals || [])
log(`Generated ${allProposals.length} candidate proposals`)

phase('Critique')
const critiques = await pipeline(
  allProposals,
  p => agent(
    `Adversarially critique this proposed change to the agent-plugins repo (/Users/gabe/Projects/agent-plugins). Read shared/constitution.md and any files named in target_files to verify feasibility and fit BEFORE judging. Reject if it duplicates existing capability, violates a constitution rule (e.g. EARS placement, 120-line reference cap, static constitution-section byte-identity, schema immutability), or is speculative/over-engineered relative to actual task need. Modify (with a concrete modification) if the core idea is sound but scoped wrong. Keep only if it survives all of that.\n\nProposal:\n${JSON.stringify(p, null, 2)}`,
    { label: `critique:${p.title.slice(0, 40)}`, phase: 'Critique', schema: CRITIQUE_SCHEMA }
  )
)

const critiqued = critiques.filter(Boolean)
const kept = critiqued.filter(c => c.verdict === 'keep')
const modified = critiqued.filter(c => c.verdict === 'modify')
const rejected = critiqued.filter(c => c.verdict === 'reject')
log(`Critique results: ${kept.length} kept, ${modified.length} modify, ${rejected.length} rejected`)

phase('Synthesize')
const synthesis = await agent(
  `Write a final prioritized synthesis report for the user (Gabe, maintainer of the agent-plugins repo) on how to integrate learnings from research into TDAD-style regression prevention and spec-driven-UI-style schema governance into the agent-plugins Claude Code plugin ecosystem.\n\nAll candidate proposals with their critique verdicts:\n${JSON.stringify(allProposals.map((p, i) => ({ ...p, critique: critiqued.find(c => c.title === p.title) || critiqued[i] })), null, 2)}\n\nRejected proposals and modified proposals:\nModified: ${JSON.stringify(modified, null, 2)}\nRejected (name them briefly and why, do not dwell): ${JSON.stringify(rejected.map(r => r.title + ': ' + r.reasoning), null, 2)}\n\nWrite a tight, prioritized report: only proposals with verdict keep or modify survive as recommendations (apply the modification text where given). Group by plugin/area. For each surviving recommendation give: what to build, target files, effort/impact, and one-sentence rationale. End with a suggested build order. No preamble, no restating the research findings at length — the user already has that context. Return plain text/markdown suitable for a chat response, not a schema.`,
  { label: 'final-synthesis', phase: 'Synthesize' }
)

return { synthesis, stats: { findings: allFindings.length, proposals: allProposals.length, kept: kept.length, modified: modified.length, rejected: rejected.length } }

export const meta = {
  name: 'agent-plugins-fe-design-expansion',
  description: 'Research frontend/design-system tooling and propose how agent-plugins should expand beyond backend/CLI into FE and design work',
  phases: [
    { title: 'Research' },
    { title: 'Ideate' },
    { title: 'Critique' },
    { title: 'Synthesize' },
  ],
}

const RESEARCH_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['findings', 'reasoning'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['topic', 'finding', 'relevance'],
        properties: {
          topic: { type: 'string' },
          finding: { type: 'string' },
          source: { type: 'string' },
          relevance: { type: 'string' },
        },
      },
    },
    reasoning: { type: 'string' },
  },
}

const PROPOSAL_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['proposals'],
  properties: {
    proposals: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['title', 'description', 'target_files', 'effort', 'impact', 'rationale'],
        properties: {
          title: { type: 'string' },
          description: { type: 'string' },
          target_files: { type: 'array', items: { type: 'string' } },
          effort: { enum: ['low', 'medium', 'high'] },
          impact: { enum: ['low', 'medium', 'high'] },
          rationale: { type: 'string' },
        },
      },
    },
  },
}

const CRITIQUE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['title', 'verdict', 'reasoning'],
  properties: {
    title: { type: 'string' },
    verdict: { enum: ['keep', 'reject', 'modify'] },
    reasoning: { type: 'string' },
    modification: { type: 'string' },
  },
}

phase('Research')
log('Fanning out research on FE/design tooling and auditing repo for existing FE coverage')

const researchTasks = [
  () => agent(
    `Web-research spec-driven and AI-assisted frontend component development beyond Nathan Curtis's "spec-driven-ui-component-development" article. Look for: component contract testing (visual regression, Chromatic/Percy, Storybook interaction tests), design-token pipelines (Style Dictionary, Tokens Studio), accessibility-as-spec approaches (axe-core contracts, WCAG acceptance criteria patterns), AI agents generating/reviewing React or design-system components in 2025/2026, and how teams verify a component implementation matches a design spec automatically. Search the web. Return findings topic/finding/source/relevance.`,
    { label: 'web:fe-component-research', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Web-research AI-assisted UI/UX design workflows and design-to-code pipelines beyond generic "Figma to code" tools. Look for: how design QA (visual diffing, token drift detection, a11y regression) is automated, how design systems version and communicate breaking changes to consuming teams, and any emerging patterns for an LLM agent acting as a design-system reviewer or design-spec drafter (analogous to how "canon" drafts specs from requirements here). Search the web. Return findings topic/finding/source/relevance.`,
    { label: 'web:design-workflow-research', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Read the agent-plugins repo at /Users/gabe/Projects/agent-plugins deeply. This repo has 9 plugins (axiom, basis, canon, delta, graph, lambda, proof, trace, vector) that are entirely backend/CLI/general-code oriented — read shared/constitution.md, shared/references/ (note there is no frontend or design-related reference file, only rust/typescript hazards), and every plugins/*/agents/*.md to confirm whether ANY existing agent has frontend-, UI-, component-, accessibility-, or design-specific judgment (as opposed to generic "TypeScript/JavaScript" backend hazards). Also check plugins/*/skills/*/SKILL.md descriptions for any FE-specific trigger phrases. Separately, note that the Claude Code harness itself already ships built-in skills called "design" (Claude Design canvas for mockups/UI) and "dataviz" (chart/visualization design system) — these are NOT part of this repo's plugin ecosystem. Return a precise gap analysis: what FE/design capability is completely absent from this repo's plugin lineup, with file:line evidence.`,
    { label: 'repo:fe-gap-scan', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
  () => agent(
    `Read the agent-plugins repo at /Users/gabe/Projects/agent-plugins deeply, focused on plugins/canon (spec drafting/gating/auditing) and shared/schemas/spec@1.json, shared/schemas/arch-spec@1.json. Assess whether canon's spec@1 schema and its acceptance-criteria model ("falsifiable, confirmable by a tester with no implementation knowledge") is naturally extensible to UI component specs (props/variants/states/accessibility criteria) the way Curtis describes Figma-generated component specs, or whether component specs need a genuinely different schema shape (visual/interaction criteria aren't testable the same way as backend behavior). Also read plugins/vector and plugins/lambda agent files to assess whether their TDD-first, file-path-exact planning model transfers to component implementation work (e.g., can "write failing test first" mean a Storybook interaction test or visual snapshot test?). Return findings with file:line evidence and an explicit opinion on schema reuse vs new schema.`,
    { label: 'repo:canon-lambda-fe-fit', phase: 'Research', schema: RESEARCH_SCHEMA }
  ),
]

const researchResults = (await parallel(researchTasks)).filter(Boolean)
const allFindings = researchResults.flatMap(r => r.findings || [])
log(`Collected ${allFindings.length} findings across ${researchResults.length} research agents`)

phase('Ideate')
const findingsText = JSON.stringify(allFindings, null, 2)

const angles = [
  {
    key: 'new-plugin-shape',
    prompt: `Based on this research on FE/design-system tooling and the agent-plugins repo's gap analysis:\n\n${findingsText}\n\nPropose the shape of a NEW plugin (or extension of an existing one — argue for whichever fits the repo's existing conventions better) that gives this ecosystem frontend/component/design-system capability, following the repo's existing conventions in shared/constitution.md (5-part agent structure, EARS placement, plugin.json layout in plugins/<id>/). Read shared/constitution.md and one existing plugin (e.g. plugins/proof) as a structural template before proposing. Produce 2-4 concrete, scoped proposals — could be a full new plugin, or targeted additions to canon/lambda/proof. Be specific about what agents it would need and what schema(s) it would introduce.`,
  },
  {
    key: 'reference-and-hazards',
    prompt: `Based on this research:\n\n${findingsText}\n\nThe repo already has a strong pattern: shared/references/typescript-hazards.md, rust-hazards.md, typescript-smells.md etc., loaded via <load_first> by proof's scanner/adversary agents. Propose concrete new reference files (e.g. a frontend-a11y-hazards.md, design-token-drift.md, component-contract-smells.md) that would let proof/lambda apply the SAME scanning/TDD machinery to frontend code, without inventing new agents. Read shared/references/typescript-hazards.md first to match its actual format and level of specificity. Produce 2-4 concrete, scoped proposals with example hazard patterns.`,
  },
  {
    key: 'spec-schema-fit',
    prompt: `Based on this research:\n\n${findingsText}\n\nFocus specifically on whether shared/schemas/spec@1.json needs a sibling schema for UI component specs (props/variants/accessibility/visual states) or whether existing acceptance_criteria can express these. Read shared/schemas/spec@1.json and shared/schemas/arch-spec@1.json first. Propose 1-3 concrete, scoped schema/agent changes (e.g. a component-spec@1.json, or new criteria types on spec@1). Be skeptical: if extending spec@1 truly suffices, say so and propose the minimal criteria-type addition instead of a new schema.`,
  },
]

const ideationResults = (await parallel(angles.map(a => () =>
  agent(a.prompt, { label: `ideate:${a.key}`, phase: 'Ideate', schema: PROPOSAL_SCHEMA })
))).filter(Boolean)

const allProposals = ideationResults.flatMap(r => r.proposals || [])
log(`Generated ${allProposals.length} candidate proposals`)

phase('Critique')
const critiques = await pipeline(
  allProposals,
  p => agent(
    `Adversarially critique this proposed change to the agent-plugins repo (/Users/gabe/Projects/agent-plugins). Read shared/constitution.md and any files named in target_files to verify feasibility and fit BEFORE judging. Reject if it duplicates existing capability (including the harness's own built-in "design" or "dataviz" skills, which are separate from this repo and should not be redundantly rebuilt here), violates a constitution rule (5-part agent structure, EARS placement, plugin directory layout, schema immutability, 120-line reference cap), or is speculative relative to real need. Modify (with a concrete modification) if the core idea is sound but scoped wrong or overlaps with the harness's built-in design/dataviz skills in a way that should be narrowed to avoid duplication. Keep only if it survives all of that.\n\nProposal:\n${JSON.stringify(p, null, 2)}`,
    { label: `critique:${p.title.slice(0, 40)}`, phase: 'Critique', schema: CRITIQUE_SCHEMA }
  )
)

const critiqued = critiques.filter(Boolean)
const kept = critiqued.filter(c => c.verdict === 'keep')
const modified = critiqued.filter(c => c.verdict === 'modify')
const rejected = critiqued.filter(c => c.verdict === 'reject')
log(`Critique results: ${kept.length} kept, ${modified.length} modify, ${rejected.length} rejected`)

phase('Synthesize')
const synthesis = await agent(
  `Write a final prioritized synthesis report for the user (Gabe, maintainer of the agent-plugins repo) on how to expand the agent-plugins ecosystem to support frontend development and design work, not just backend/CLI tooling.\n\nAll candidate proposals with their critique verdicts:\n${JSON.stringify(allProposals.map((p, i) => ({ ...p, critique: critiqued.find(c => c.title === p.title) || critiqued[i] })), null, 2)}\n\nModified: ${JSON.stringify(modified, null, 2)}\nRejected (name briefly, do not dwell): ${JSON.stringify(rejected.map(r => r.title + ': ' + r.reasoning), null, 2)}\n\nWrite a tight, prioritized report: only keep/modify verdicts survive as recommendations (apply modification text where given). For each: what to build, target files, effort/impact, one-sentence rationale. Explicitly address whether this should be a new plugin or an extension of canon/lambda/proof, and how it relates to (without duplicating) the harness's built-in design/dataviz skills. End with a suggested build order. No preamble, no restating research findings at length. Return plain markdown suitable for a chat response.`,
  { label: 'final-synthesis', phase: 'Synthesize' }
)

return { synthesis, stats: { findings: allFindings.length, proposals: allProposals.length, kept: kept.length, modified: modified.length, rejected: rejected.length } }

